\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}

\title{KCRL 92.7 Community FM\\Station Operations Handbook}
\author{Engineering Committee}
\date{August 2026}

\begin{document}
\maketitle

\section{About This Handbook}
This handbook documents the daily operation and the preventive
maintenance of the KCRL 92.7 community FM station, a 200-watt
non-commercial service run entirely by volunteers. It is written for
the duty operators who open and close the studio and for the two
technicians who look after the transmitter site on Ridge Road.

Grounding work at the transmitter site is described in
Section~\ref{sec:m:ground}; it must be scheduled before the wet season
and signed off in the engineering log.

\input{sections/maintenance}
\input{sections/operations}

\section{Engineering Log}
Every visit to the transmitter site is recorded in the engineering log:
date, crew, work performed, and meter readings before and after. The
log book lives in the rack drawer, and a scanned copy is uploaded to
the shared drive on the first Monday of each month.
\end{document}

